"""Control for a mechanical short-word preference at a fixed writing margin."""
import json
from random import Random
from statistics import median

from measure import test

WIDTHS = (40, 50, 60)
SEEDS = tuple(range(281145,281155))


def paragraphs(seed):
    rng=Random(seed)
    return [[rng.randint(1,3) if rng.random()<.25 else rng.randint(4,9) for _ in range(rng.randint(14,35))]
            for _ in range(120)]


def rows_of(pars,width):
    for para in pars:
        current=[]; length=0
        for word in para:
            cost=word+bool(current)
            if length+cost>width:
                yield current
                current=[]; length=0; cost=word
            current.append(word); length+=cost
        if current:
            yield current


def main():
    output={}
    for width in WIDTHS:
        outcomes=[]
        for seed in SEEDS:
            lines=list(rows_of(paragraphs(seed),width))
            flagged=[(True,[int(n<=3) for n in words],tuple((i==len(words)-1,0<i<len(words)-1) for i in range(len(words)))) for words in lines]
            outcomes.append({'seed':seed,'lines':len(lines),**test(flagged,99)})
        output[width]={'pass_count':sum(row['pass'] for row in outcomes), 'median_ratio':median(row['value'] for row in outcomes), 'rows':outcomes}
    print(json.dumps(output,indent=2))


if __name__=='__main__':
    main()

