"""Public diagnostic with initial and uncertain slots fixed and one certain final per line."""
import json

import numpy as np
from vs import corpus, dsl
from measure import group_toks


def short(w):
    return 1<=len(dsl.SEG(w))<=3


def endpoint_test(groups, minimum, maximum):
    probabilities = []
    short_finals = short_interiors = interiors = 0
    for line in groups.values():
        if line[0]['unit']!='P' or not minimum<=line[0]['n']<=maximum:
            continue
        endpoint = [t for t in line if t['k']==t['n']-1 and not dsl.UNCERTAIN(t['w'])]
        mid = [t for t in line if 0<t['k']<t['n']-1 and not dsl.UNCERTAIN(t['w'])]
        if len(endpoint)!=1 or not mid:
            continue
        ends=short(endpoint[0]['w']); body=sum(short(t['w']) for t in mid)
        short_finals+=ends; short_interiors+=body; interiors+=len(mid)
        probabilities.append((ends+body)/(1+len(mid)))
    distribution = np.array([1.])
    for p in probabilities:
        update = np.zeros(len(distribution)+1)
        update[:-1] += (1-p)*distribution
        update[1:] += p*distribution
        distribution = update
    lines=len(probabilities)
    return {'lines':lines,'final_hits':short_finals,'interior_hits':short_interiors,'interior_words':interiors,
            'ratio':(short_finals/lines)/(short_interiors/interiors),
            'p_exact_upper':float(distribution[short_finals:].sum())}


def main():
    out={}
    for edition in ('zl','it','rf'):
        _,pages=corpus.split_pages('practice',edition)
        groups=group_toks(pages)
        out[edition]={name:endpoint_test(groups,lo,hi) for name,lo,hi in [('all_eligible',3,999),('3–5 words',3,5),('6 or more words',6,999)]}
    print(json.dumps(out,indent=2))


if __name__=='__main__':
    main()
